leftG.circle(5).center(LC.x, LC.y).fill('#222');
lbl(leftG, 'z', LC.x - 14, LC.y - 12, 15);

// dynamic left group
var dynL = draw.group();
// R arrow to lower-left rim (static)
arrow(dynL, LC.x, LC.y, LC.x - RR * 0.707, LC.y + RR * 0.707, '#222', 1.3, true);
lbl(dynL, 'R', LC.x - RR * 0.55 - 8, LC.y + RR * 0.42, 17);

var ringL = dynL.circle(0).fill('none').stroke({ color: '#e08633', width: 8, opacity: 0.9 });
var rArrowL = null, drArrowL = null, rLblL = null, drLblL = null;
ringL.css('cursor', 'pointer');
ringL.on('mousemove', function (e) { showTooltip('Thin ring: every point is at the same distance r from the axis', e); })
     .on('mouseleave', hideTooltip)
     .on('click', function () { showPopup('Annular ring', 'Slice the disk into concentric rings. One ring of radius r and width dr has all its mass dm at the same distance r from the axis, so its moment of inertia is just r²·dm.'); });

function rebuildLeftArrows(r, dr) {
  if (rArrowL) { rArrowL.remove(); drArrowL.remove(); rLblL.remove(); drLblL.remove(); }
  var a = Math.PI / 4; // down-right ray for r
  var rr = r * RR;
  rArrowL = arrow(dynL, LC.x, LC.y, LC.x + rr * Math.cos(a), LC.y + rr * Math.sin(a), '#222', 1.3, true);
  rLblL = lbl(dynL, 'r', LC.x + rr * Math.cos(a) * 0.62 + 12, LC.y + rr * Math.sin(a) * 0.62 + 10, 17);
  // dr arrow straddles the band radially along the upper-right ray
  var a2 = -Math.PI / 4;
  var ca = Math.cos(a2), sa = Math.sin(a2);
  var half = Math.max(dr * RR, 6) / 2 + 4;
  var rm = r * RR;
  var x1 = LC.x + (rm - half) * ca, y1 = LC.y + (rm - half) * sa;
  var x2 = LC.x + (rm + half) * ca, y2 = LC.y + (rm + half) * sa;
  drArrowL = arrow(dynL, x1, y1, x2, y2, '#222', 1.3, true);
  drLblL = lbl(dynL, 'dr', x2 + 24, y2 - 16, 17);
}

// ---------- RIGHT PANEL (perspective) ----------
var RC = { x: 655, y: 250 }, RX = 175, RY = 55;
var rightG = draw.group();
// axes
arrow(rightG, RC.x, RC.y, RC.x, RC.y - 195, '#222', 1.5);
lbl(rightG, 'z', RC.x - 2, RC.y - 210);
arrow(rightG, RC.x - 30, RC.y, RC.x + RX + 35, RC.y, '#222', 1.5);
lbl(rightG, 'y', RC.x + RX + 48, RC.y + 4);
arrow(rightG, RC.x, RC.y, RC.x - 62, RC.y + 78, '#222', 1.5);
lbl(rightG, 'x', RC.x - 74, RC.y + 92);
// disk ellipse — rim matches the disk shading; only the annulus is orange
rightG.ellipse(2 * RX, 2 * RY).center(RC.x, RC.y).fill('#c3cdea').stroke({ color: '#8fa0c8', width: 1.2 });
rightG.circle(5).center(RC.x, RC.y).fill('#222');
// rotation arrow looping around z axis
var rotPath = rightG.path('M ' + (RC.x - 62) + ' ' + (RC.y - 150) +
  ' A 62 16 0 1 1 ' + (RC.x + 62) + ' ' + (RC.y - 150)).fill('none').stroke({ color: '#222', width: 1.6 });
rotPath.attr('marker-end', mk);
rotPath.css('cursor', 'pointer');
rotPath.on('mousemove', function (e) { showTooltip('The disk spins about the z axis', e); }).on('mouseleave', hideTooltip);

// dynamic right group
var dynR = draw.group();
var ringR = dynR.ellipse(0, 0).fill('none').stroke({ color: '#e08633', width: 6, opacity: 0.95 });
var dmDot = dynR.circle(9).fill('#a33b1f').stroke({ color: '#fff', width: 1 });
var rArrowR = null, dmLblR = null, rLblR = null;
ringR.css('cursor', 'pointer');
ringR.on('mousemove', function (e) { showTooltip('The same ring, seen edge-on: a full annulus at radius r', e); }).on('mouseleave', hideTooltip);
dmDot.css('cursor', 'pointer');
dmDot.on('mousemove', function (e) { showTooltip('Mass element dm riding the ring', e); }).on('mouseleave', hideTooltip)
     .on('click', function () { showPopup('Mass element dm', 'A small piece of the ring. Its contribution to the moment of inertia is r²·dm, and every piece of the ring shares the same r — so the whole ring contributes r²·dm_ring.'); });

function rebuildRight(r, dr) {
  ringR.size(2 * r * RX, 2 * r * RY).center(RC.x, RC.y);
  ringR.stroke({ width: Math.max(3, dr * RR * 0.55) });
  // remove the previous dynamic labels BEFORE creating new ones (no leaks)
  if (rArrowR) { rArrowR.remove(); rArrowR = null; }
  if (dmLblR) { dmLblR.remove(); dmLblR = null; }
  if (rLblR) { rLblR.remove(); rLblR = null; }
  var th = -Math.PI / 5; // upper-right
  var px = RC.x + r * RX * Math.cos(th), py = RC.y + r * RY * Math.sin(th);
  rArrowR = arrow(dynR, RC.x, RC.y, px, py, '#222', 1.3, true);
  dmDot.center(px, py);
  dmLblR = lbl(dynR, 'dm', px + 26, py - 16, 17);
  rLblR = lbl(dynR, 'r', RC.x + (px - RC.x) * 0.5 - 12, RC.y + (py - RC.y) * 0.5 + 16, 17);
}

// ---------- readout / contribution bar ----------
var readout = draw.text('').font({ size: 14, family: 'sans-serif' }).fill('#222').move(410, 360);
var barBg = draw.rect(200, 14).move(410, 385).fill('#eee').stroke({ color: '#aaa', width: 1 });
var barFg = draw.rect(0, 14).move(410, 385).fill('#e08633');
var barLbl = draw.text('r²·dm contribution').font({ size: 12, family: 'sans-serif' }).fill('#555').move(615, 385);

// ---------- state ----------
var state = { r: 0.6, dr: 0.08, persp: false };

function refresh() {
  rebuildLeftArrows(state.r, state.dr);
  ringL.radius(state.r * RR).center(LC.x, LC.y);
  ringL.stroke({ width: Math.max(3, state.dr * RR) });
  rebuildRight(state.r, state.dr);
  var dm = 2 * state.r * state.dr; // dm/M
  readout.text('dm/M = ' + dm.toFixed(3) + '    r²·dm/MR² = ' + (state.r * state.r * dm).toFixed(4));
  var maxv = 2 * 0.25;
  barFg.width(200 * Math.min(1, (state.r * state.r * dm) / maxv));
  var persp = state.persp;
  rightG.attr('opacity', persp ? 1 : 0.35);
  dynR.attr('opacity', persp ? 1 : 0.35);
  leftG.attr('opacity', persp ? 0.35 : 1);
  dynL.attr('opacity', persp ? 0.35 : 1);
}

function update_ringRadius(v) { state.r = v; refresh(); }
function update_ringWidth(v) { state.dr = v; refresh(); }
function toggle_viewToggle(on) { state.persp = on; refresh(); }

// ---------- demo steps ----------
var steps = [
  { title: 'Slice the disk into rings', r: 0.6, dr: 0.08, persp: false,
    narration: 'The disk is decomposed into thin concentric rings. The highlighted orange ring sits at radius r with thickness dr — every bit of its mass is the same distance from the axis.' },
  { title: 'Move the ring outward', r: 0.95, dr: 0.08, persp: false,
    narration: 'Drag r toward the rim: the ring\'s r²·dm contribution grows quadratically. Mass near the edge contributes far more than the same mass near the center.' },
  { title: 'Widen the strip', r: 0.6, dr: 0.22, persp: false,
    narration: 'Increase dr and watch the strip area — and hence dm — grow. In the limit dr → 0 the ring becomes dm = (2M/R²)·r·dr inside the integral.' },
  { title: 'See it in perspective', r: 0.6, dr: 0.08, persp: true,
    narration: 'The tilted view: the same ring wraps around the vertical z axis as the disk spins, and the dm marker rides the ring — the integration element is a full annulus at one radius.' }
];
var curStep = 0;
function applyStep(i) {
  curStep = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[curStep];
  document.getElementById('ringRadiusInput').value = s.r;
  document.getElementById('ringRadiusVal').value = s.r.toFixed(2);
  document.getElementById('ringWidthInput').value = s.dr;
  document.getElementById('ringWidthVal').value = s.dr.toFixed(2);
  document.getElementById('viewToggleInput').checked = s.persp;
  state.r = s.r; state.dr = s.dr; state.persp = s.persp;
  document.getElementById('demoNarration').textContent = (curStep + 1) + '. ' + s.title + ' — ' + s.narration;
  document.getElementById('stepLabel').textContent = (curStep + 1) + ' / ' + steps.length;
  refresh();
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

